import{z as A,x as i,o as e,c as p,q as o,j as l,D as E,d as B,s,S as n,b as r}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"ESG 理论","description":"","frontmatter":{"title":"ESG 理论","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/esg-theory.md","filePath":"econ/esg-theory.md","lastUpdated":1791063341000}'),d={name:"econ/esg-theory.md"};function h(m,a,S,c,D,u){const t=i("Mermaid");return e(),p("div",null,[a[2]||(a[2]=o('<h1 id="esg-理论" tabindex="-1">ESG 理论 <a class="header-anchor" href="#esg-理论" aria-label="Permalink to &quot;ESG 理论&quot;">​</a></h1><div class="epigraph"><p>若一部分投资者对绿色或社会属性有偏好，资产价格可以含非金钱收益；这不等于「ESG 提高了所有人的 $\\alpha$」。</p><footer>—— 对照 Pástor, Stambaugh and Taylor 的可持续投资均衡；Oehmke and Opp 对公司激励</footer></div><p><a href="/econ/cash-holdings">上一课</a>把现金当治理与摩擦下的存量。缺口是目标函数本身：股东是否只最大化财务价值。本课钉 ESG 作为偏好与约束，家族企业下一课才讲控制权结构。不把量化栏的 ESG 因子辩论再写一遍，只给公司金融一侧的均衡语言。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Hart–Zingales：若股东在商品市场也有社会偏好，最大化利润不必是一致的目标。Pástor–Stambaugh–Taylor：绿资产被偏好持有，预期金钱回报可以更低（持有人消费了「温暖」）。若把 ESG 写成无成本的 alpha，会与「谁在出钱买偏好」矛盾。缺口是分清偏好、风险管理、与代理（经理用 ESG 掩盖绩效）。</p><p><span class="marginnote">术语翻译：「温暖发光」（warm glow）指投资者从「我持有干净的公司」这件事本身获得的满足，和捐款时的心理回报同类。它是一种真实收益——只是不走账户，所以愿意接受更低的金钱回报，价格里于是出现绿棕价差。</span></p><p><span class="marginnote">Friedman 的股东价值是基准对照，不是本课要重判的道德。Hong and Kacperczyk 的罪股溢价是价格含义的早期证据线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两块：偏好（效用含 \\(E,S,G\\) 属性）与生产（减排成本、诉讼）。均衡：绿资本成本下降，棕资本成本上升，激励真实投资直到边际成本等于价差。约束型 ESG（排除）改变风险分担，可能提高被排除资产的预期回报。治理：披露与评级是噪声信号，评级分歧本身是识别问题（后课实证识别）。</p>',9)),(e(),l(n,null,{default:E(()=>[s(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PREF%5B%22%E6%8A%95%E8%B5%84%E8%80%85%E5%81%8F%E5%A5%BD%22%5D%20--%3E%20P%5B%22%E7%BB%BF%E6%A3%95%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20P%20--%3E%20I%5B%22%E5%85%AC%E5%8F%B8%E6%8A%95%E8%B5%84%22%5D%0A%20%20AG%5B%22%E4%BB%A3%E7%90%86%20%2F%20%E6%BC%82%E7%BB%BF%22%5D%20--%3E%20NOI%5B%22%E4%BB%B7%E6%A0%BC%E5%99%AA%E5%A3%B0%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[B("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"价差是偏好强度 × 资本供给弹性。若绿技术供给很快，价差消失，金钱 alpha 也消失——这是成功，不是因子失效。漂绿使信号与真实 \\(E\\) 脱钩，价差变成营销均衡。",-1)),(e(),l(n,null,{default:E(()=>[s(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20PREF%5B%22%E7%BB%BF%E5%81%8F%E5%A5%BD%E5%BC%BA%E5%BA%A6%22%5D%20--%3E%20SPREAD%5B%22%E7%BB%BF%E6%A3%95%E8%B5%84%E6%9C%AC%E6%88%90%E6%9C%AC%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20SUPPLY%5B%22%E7%BB%BF%E8%89%B2%E8%B5%84%E6%9C%AC%E4%BE%9B%E7%BB%99%E5%BC%B9%E6%80%A7%22%5D%20--%3E%20SPREAD%0A%20%20SPREAD%20--%3E%20INVEST%5B%22%E7%BB%BF%E8%89%B2%E7%9C%9F%E5%AE%9E%E6%8A%95%E8%B5%84%E5%A2%9E%E5%8A%A0%22%5D%0A%20%20INVEST%20--%3E%20SCALE%5B%22%E7%BB%BF%E6%8A%80%E6%9C%AF%E8%A7%84%E6%A8%A1%E4%B8%8A%E5%8D%87%22%5D%0A%20%20SCALE%20--%3E%20FADE%5B%22%E4%BB%B7%E5%B7%AE%E7%BC%A9%E5%B0%8F%3A%20%E9%87%91%E9%92%B1%20alpha%20%E6%B6%88%E5%A4%B1%22%5D%0A%20%20GREENWASH%5B%22%E6%BC%82%E7%BB%BF%3A%20%E4%BF%A1%E5%8F%B7%E4%B8%8E%E7%9C%9F%E5%AE%9E%20E%20%E8%84%B1%E9%92%A9%22%5D%20--%3E%20FAKE%5B%22%E8%90%A5%E9%94%80%E5%9D%87%E8%A1%A1%3A%20%E4%BB%B7%E5%B7%AE%E5%A4%B1%E7%9C%9F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">数字实例：同样每年 10 元的永续现金流，折现率 7% 值约 143 元、5% 值 200 元——2 个百分点的绿棕价差就让绿项目贵四成。资本成本这点小价差，正是把偏好传导成真实减排投资的杠杆。</span></p><p><span class="marginnote">常见误区：「绿资产跑赢才说明 ESG 有效」。均衡逻辑恰好相反：偏好把绿资产价格买高、预期回报压低，价差因此趋于消失——alpha 蒸发是偏好被满足、资本起作用的证据，不是策略失败。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评估某评级商。量化课的 ESG 因子是收益侧；这里是目标与资本成本。下一课金字塔控股是另一类「谁的偏好进目标函数」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ESG 首先改变谁的偏好进入目标，其次才可能改变 alpha。</li><li>绿资本成本下降是机制，不是免费午餐。</li><li>出处：Pástor–Stambaugh–Taylor；Hart–Zingales；Hong–Kacperczyk 罪股。</li></ul>',6))])}const C=A(d,[["render",h]]);export{g as __pageData,C as default};
